import { Component } from '@angular/core';
import { MisComprasService } from 'src/app/services/mis-compras.service';
import { UsuarioService } from 'src/app/services/usuario.service';

@Component({
  selector: 'app-ejercicio-buscador',
  templateUrl: './ejercicio-buscador.component.html',
  styleUrls: ['./ejercicio-buscador.component.css']
})
export class EjercicioBuscadorComponent {

  public nombreProducto: string = "";
  public cantidadCompras: number | null = null;
  public emailUsuario: string = "";


  constructor(public misComprasService: MisComprasService, public usuarioService: UsuarioService){}


  ngOnInit(): void {
    this.emailUsuario = this.usuarioService.obtenerEmailUsuarioLogeado();
  }


  buscarProducto(): void{
    this.misComprasService.contarComprasUsuario(this.emailUsuario, this.nombreProducto).subscribe(
      (res: any) =>{
        this.cantidadCompras = res;
      });
  }

}
<div>
  Buscador de productos: <br>
  <input type="text" placeholder="Nombre del Producto:" [(ngModel)]="nombreProducto">
  <button type="button" (click)="buscarProducto()">Buscar</button>


  <!--Para mostrar la cantidad-->
  <div *ngIf="cantidadCompras!=null"> <!--Si las compras no esta vacias-->

  </div>

</div>
